process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='', AKC='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'akc4', content:b64}; if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'akc4');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'AKC4'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  let s=await snip('TEMP akc4 set kat', "update_option('ps_uxd_kat','"+KAT+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  s=await snip('TEMP akc4 set akc', "update_option('ps_uxd_akc','"+AKC+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP akc4 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd5=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw=(await resp.text()).slice(0,300); }
  await pause(1500);
  resp=await fetch(`${WP}/?ps_uxv6=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.verify=JSON.parse(await resp.text()); }catch(e){ out.verify_raw=(await resp.text()).slice(0,400); }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.setDefaultTimeout(12000);
  await page.goto(`${WP}/?ps_uxlog2=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});
  await pause(1500);
  out.url=page.url();
  out.sarasas=await page.evaluate(()=>{
    const t=document.querySelector('.psakc-app'); return t?t.innerText.slice(0,400):null; });
  let png=await page.screenshot(); out.s1=await putRaw('screenshots/akc4_sarasas.png', png.toString('base64'),'akc4');

  /* Nauja akcija */
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-akcijos&nauja=1`,{waitUntil:'networkidle',timeout:60000});
  await pause(1500);
  out.forma=await page.evaluate(()=>{
    const f=document.querySelector('.psakc-forma'); if(!f) return null;
    return {tabai:Array.prototype.map.call(f.querySelectorAll('.tb'),b=>b.textContent.trim()),
      brendu:f.querySelectorAll('.varneles[data-sar=brendai] label').length,
      kategoriju:f.querySelectorAll('.varneles[data-sar=kategorijos] label').length,
      atributu:f.querySelectorAll('.atr').length,
      mygtukai:Array.prototype.map.call(f.querySelectorAll('.perz-juosta button'),b=>b.textContent.trim())};
  });
  /* Uzpildom: Ambrosia brendas -15%, perziura */
  await page.evaluate(()=>{
    document.querySelector('.f-pav').value='TESTAS Ambrosia -15%';
    document.querySelector('.f-reiksme').value='15';
    const labels=document.querySelectorAll('.varneles[data-sar=brendai] label');
    for(const l of labels){ if(l.textContent.toLowerCase().indexOf('ambrosia')>=0){ l.querySelector('input').checked=true; break; } }
  });
  await page.evaluate(()=>document.querySelector('.ak-perziureti').click());
  await pause(4000);
  out.perziura=await page.evaluate(()=>{
    const s=document.querySelector('.perz-suv'), t=document.querySelector('.perz-turinys');
    return {suvestine:s?s.innerText.replace(/\n+/g,' | '):null,
      eiluciu:t?t.querySelectorAll('.pt tbody tr').length:0,
      pirma:t&&t.querySelector('.pt tbody tr')?t.querySelector('.pt tbody tr').innerText.replace(/\n+/g,' | ').slice(0,180):null};
  });
  png=await page.screenshot(); out.s2=await putRaw('screenshots/akc4_perziura.png', png.toString('base64'),'akc4');

  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/akc4.json', out);
}
main().catch(async e=>{ await putJson('analize/akc4.json',{klaida:String(e).slice(0,400)}); });
